/** Enum values used across the app. The SQLite/D1 schema stores them as plain
 * strings, so the values live here instead of being generated by Prisma. */
export const LeadStage = {
  NEW: "NEW",
  CONTACTED: "CONTACTED",
  QUOTED: "QUOTED",
  WON: "WON",
  LOST: "LOST",
} as const;
export type LeadStage = (typeof LeadStage)[keyof typeof LeadStage];

export const FreelanceStatus = {
  NOT_STARTED: "NOT_STARTED",
  ACTIVE: "ACTIVE",
  ON_HOLD: "ON_HOLD",
  COMPLETED: "COMPLETED",
} as const;
export type FreelanceStatus = (typeof FreelanceStatus)[keyof typeof FreelanceStatus];

export const RateType = {
  HOURLY: "HOURLY",
  FIXED: "FIXED",
  RETAINER: "RETAINER",
} as const;
export type RateType = (typeof RateType)[keyof typeof RateType];

export const ClientType = {
  COMPANY: "COMPANY",
  INDIVIDUAL: "INDIVIDUAL",
} as const;
export type ClientType = (typeof ClientType)[keyof typeof ClientType];

export const TransactionType = {
  INCOME: "INCOME",
  EXPENSE: "EXPENSE",
} as const;
export type TransactionType = (typeof TransactionType)[keyof typeof TransactionType];

export const InvoiceStatus = {
  DRAFT: "DRAFT",
  SENT: "SENT",
  PAID: "PAID",
  OVERDUE: "OVERDUE",
  ACCEPTED: "ACCEPTED",
  DECLINED: "DECLINED",
} as const;
export type InvoiceStatus = (typeof InvoiceStatus)[keyof typeof InvoiceStatus];
